order_js=r'''(()=>{"use strict";const params=new URLSearchParams(location.search),form=document.querySelector("#sok-order-form"),status=document.querySelector("#sok-order-status"),skuEl=document.querySelector("#sok-order-sku"),qtyEl=document.querySelector("#sok-order-qty"),stateEl=document.querySelector("#sok-order-state"),zipEl=document.querySelector("#sok-order-zip"),modeEl=document.querySelector("#sok-order-mode"),titleEl=document.querySelector("#sok-order-title"),productEl=document.querySelector("#sok-order-product"),intentEl=document.querySelector("#sok-order-intent"),islandEl=document.querySelector("#sok-order-island"),nameEl=document.querySelector("#sok-order-name"),emailEl=document.querySelector("#sok-order-email"),phoneEl=document.querySelector("#sok-order-phone"),notesEl=document.querySelector("#sok-order-notes"),emailLink=document.querySelector("#sok-order-email-link");const sku=String(params.get("sku")||"").trim().toUpperCase(),mode=String(params.get("mode")||"").trim().toLowerCase(),allowedIntents=new Set(["purchase_options","product","commercial","hawaii"]);let intent=String(params.get("intent")||"purchase_options").trim().toLowerCase(),product=null,started=false;if(!allowedIntents.has(intent))intent="purchase_options";skuEl.value=sku;intentEl.value=intent;if(params.get("qty"))qtyEl.value=params.get("qty");if(params.get("state"))stateEl.value=String(params.get("state")).trim().toUpperCase();const track=(type,details={})=>window.EUSIntent?.track?.(type,sku,{source:"sok-order",sku,...details});const quantityBand=()=>{const q=Math.max(1,Number.parseInt(qtyEl.value||"1",10)||1);return q>=4?"4plus":String(q)};function updateHawaii(announce=false){const hi=stateEl.value.trim().toUpperCase()==="HI"||intent==="hawaii";document.querySelectorAll("[data-hawaii-field]").forEach(x=>x.hidden=!hi);islandEl.required=hi;if(hi&&intent==="hawaii")stateEl.value="HI";if(hi&&announce)track("hawaii_options_open",{quantityBand:quantityBand()});}function setIntent(next,announce=true){if(!allowedIntents.has(next))next="purchase_options";if(product?.publicPurchaseMode==="COMMERCIAL_ONLY")next="commercial";if(next==="hawaii"&&!product?.batteryRelevant&&product){next="purchase_options";if(announce)status.textContent="Hawaii battery review does not apply to this product; use Purchase Options or Commercial Pricing.";}intent=next;intentEl.value=next;if(next==="hawaii"){stateEl.value="HI";titleEl.textContent="Request Hawaii Purchase Options";if(announce)status.textContent="Hawaii selected. Add quantity, destination and one contact method.";}else if(next==="commercial"){titleEl.textContent="Request Commercial Pricing";if(announce)status.textContent="Commercial pricing selected. Add quantity, destination and one contact method.";}else if(next==="product"){titleEl.textContent="Ask About This Product";if(announce)status.textContent="Your exact SOK model stays attached to this request.";}else titleEl.textContent="Start Your Purchase Request";updateHawaii(next==="hawaii"&&announce);track(next==="hawaii"?"hawaii_options_open":next==="commercial"?"commercial_review_route":"purchase_options_open",{intent:next,quantityBand:quantityBand()});}document.querySelectorAll("[data-sok-intent]").forEach(btn=>btn.addEventListener("click",()=>{setIntent(String(btn.dataset.sokIntent||"purchase_options"));form.scrollIntoView({behavior:"smooth",block:"start"});}));stateEl.addEventListener("change",()=>updateHawaii(true));qtyEl.addEventListener("change",()=>{if((Number.parseInt(qtyEl.value||"1",10)||1)>=4)track("commercial_review_route",{reason:"quantity_4plus",quantityBand:"4plus"});});form.addEventListener("input",()=>{if(!started){started=true;track("purchase_inquiry_start",{intent:intentEl.value});}},{passive:true});if(mode==="prepurchase")modeEl.textContent="PRE-PURCHASE — Elevation confirms the current supply window before payment when required.";else if(mode==="backorder")modeEl.textContent="AVAILABLE ON BACKORDER — Elevation confirms replenishment and timing before payment when required.";fetch("/api/sok/catalog",{headers:{Accept:"application/json"},cache:"no-store"}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{product=(d.products||[]).find(p=>String(p.sku||"").toUpperCase()===sku)||null;if(!product){status.textContent="Select a current SOK product from the catalog before submitting.";form.querySelector("button[type=submit]").disabled=true;return;}productEl.textContent=`${product.sku} · ${product.title}`;emailLink.textContent="casey@elevationupscales.com";if(!product.batteryRelevant)document.querySelector('[data-sok-intent="hawaii"]').hidden=true;setIntent(intent,false);}).catch(()=>{status.textContent="Current SOK product information could not be loaded. Please return to the SOK catalog and try again.";});form.addEventListener("submit",async e=>{e.preventDefault();if(!product)return;const email=emailEl.value.trim(),phone=phoneEl.value.trim();if(!nameEl.value.trim()){status.textContent="Enter your name.";nameEl.focus();return;}if(!email&&!phone){status.textContent="Enter an email address or phone number so we can contact you.";emailEl.focus();return;}if(email&&!emailEl.validity.valid){status.textContent="Enter a valid email address or leave email blank and use a phone number.";emailEl.focus();return;}if(stateEl.value.trim().length!==2){status.textContent="Enter a two-letter destination state.";stateEl.focus();return;}updateHawaii(false);if(islandEl.required&&!islandEl.value){status.textContent="Select the Hawaii island for this request.";islandEl.focus();return;}status.textContent="Sending purchase request…";const body={intent:intentEl.value,sku:skuEl.value,quantity:Number.parseInt(qtyEl.value||"1",10)||1,destinationState:stateEl.value.trim().toUpperCase(),postalCode:zipEl.value.trim(),hawaiiIsland:islandEl.value,name:nameEl.value.trim(),email,phone,notes:notesEl.value.trim(),productUrl:`${location.origin}${product.detailUrl||location.pathname}`};try{const r=await fetch("/api/sok/reservations",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify(body)}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||"Unable to start the order");status.textContent=`${d.status}. Reference ${d.reservationId}. ${d.nextStep}`;form.querySelector("button[type=submit]").disabled=true;track("purchase_inquiry_submit",{intent:intentEl.value,quantityBand:quantityBand()});if(body.quantity>=4||d.status==="COMMERCIAL INQUIRY RECEIVED")track("commercial_review_route",{reason:"submitted_commercial",quantityBand:quantityBand()});}catch(err){status.textContent=err.message;}});})();'''
write(Path('site/sok-order.js'),order_js)

