s=replace_once(s,'if(!name||!validEmail(email))return json({error:"Name and valid email are required"},400);','if(!name||(!validEmail(email)&&!validPhone(phone)))return json({error:"Name and a valid email or phone are required"},400);','contact validation')
if 'function renderGallery(product)' not in s:
    s=replace_once(s,'function renderDownloads(product){if(!(product.downloads||[]).length)return`<p>Customer-facing literature will be attached here when an approved public file is available.</p>`;return product.downloads.map(d=>`<a class="sok-literature-link" href="${esc(d.url)}">${esc(d.label)}</a>`).join("");}', 'function renderDownloads(product){if(!(product.downloads||[]).length)return`<p>Customer-facing literature will be attached here when an approved public file is available.</p>`;return product.downloads.map(d=>`<a class="sok-literature-link" href="${esc(d.url)}">${esc(d.label)}</a>`).join("");}\nfunction renderGallery(product){const images=(product.images||[product.primaryImage]).filter(Boolean);if(images.length<2)return"";return `<section class="sok-product-section sok-product-section--wide"><p class="eyebrow">PRODUCT MEDIA</p><h2>Approved SOK product imagery.</h2><div class="sok-product-gallery">${images.map((src,i)=>`<a class="sok-gallery-item" data-sok-page-action="media" data-sok-media-index="${i+1}" href="${esc(src)}" target="_blank" rel="noopener"><img src="${esc(src)}" alt="${esc(product.title)}${i?" system example":""}" loading="lazy" decoding="async"><span>${i===0?"Product view":"System / rack example — components shown may be sold separately"}</span></a>`).join("")}</div></section>`;}','gallery helper')
