s=s.replace('/site-shell.js?v=4.5.2','/site-shell.js?v=4.8.0').replace('/sok-static-product.js?v=4.7.0','/sok-static-product.js?v=4.8.0').replace('/sok-commercialization.css?v=4.7.0','/sok-commercialization.css?v=4.8.0')
